-- Excluded immutable adoption preparation. Activation remains a separate guarded command.
CREATE TABLE app_collection_legacy_preparations (
 id TEXT PRIMARY KEY,economic_audit_id TEXT NOT NULL UNIQUE REFERENCES app_collection_legacy_economics(id),operator TEXT NOT NULL,
 parent_digest TEXT NOT NULL CHECK(length(parent_digest)=64 AND parent_digest NOT GLOB '*[^0-9a-f]*'),
 state TEXT NOT NULL CHECK(state IN ('working','prepared','held')),phase TEXT NOT NULL CHECK(phase IN ('inspect','stages','admissions','objects','closure','finish')),
 revision INTEGER NOT NULL CHECK(revision BETWEEN 0 AND 9007199254740991),stage_index INTEGER NOT NULL CHECK(stage_index BETWEEN 0 AND 32),admission_index INTEGER NOT NULL CHECK(admission_index BETWEEN 0 AND 1000),object_cursor INTEGER NOT NULL CHECK(object_cursor BETWEEN 0 AND 2048),
 chain_digest TEXT NOT NULL CHECK(length(chain_digest)=64 AND chain_digest NOT GLOB '*[^0-9a-f]*'),result_digest TEXT CHECK(result_digest IS NULL OR length(result_digest)=64 AND result_digest NOT GLOB '*[^0-9a-f]*'),
 last_nonce TEXT NOT NULL,quiescence_json TEXT CHECK(quiescence_json IS NULL OR json_valid(quiescence_json) AND length(CAST(quiescence_json AS BLOB))<=8192),result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json) AND length(CAST(result_json AS BLOB))<=16384),reason TEXT,created_ms INTEGER NOT NULL CHECK(created_ms BETWEEN 0 AND 8640000000000000),updated_ms INTEGER NOT NULL CHECK(updated_ms BETWEEN created_ms AND 8640000000000000),
 CHECK((state='prepared' AND phase='finish' AND result_json IS NOT NULL AND result_digest IS NOT NULL) OR (state<>'prepared' AND result_json IS NULL AND result_digest IS NULL)),
 CHECK((state='held' AND reason IS NOT NULL) OR (state<>'held' AND reason IS NULL))
) STRICT;
CREATE TABLE app_collection_legacy_prepared_stages (
 preparation_id TEXT NOT NULL REFERENCES app_collection_legacy_preparations(id),stage_index INTEGER NOT NULL CHECK(stage_index BETWEEN 0 AND 31),stage_id TEXT NOT NULL,
 operation_id TEXT NOT NULL UNIQUE,claim_nonce TEXT NOT NULL UNIQUE,request_key TEXT NOT NULL UNIQUE,
 body_json TEXT NOT NULL CHECK(json_valid(body_json) AND length(CAST(body_json AS BLOB))<=16384),body_digest TEXT NOT NULL CHECK(length(body_digest)=64 AND body_digest NOT GLOB '*[^0-9a-f]*'),source_proof_digest TEXT NOT NULL CHECK(length(source_proof_digest)=64 AND source_proof_digest NOT GLOB '*[^0-9a-f]*'),prior_chain_digest TEXT NOT NULL CHECK(length(prior_chain_digest)=64 AND prior_chain_digest NOT GLOB '*[^0-9a-f]*'),chain_digest TEXT NOT NULL CHECK(length(chain_digest)=64 AND chain_digest NOT GLOB '*[^0-9a-f]*'),run_revision INTEGER NOT NULL CHECK(run_revision BETWEEN 1 AND 9007199254740991),PRIMARY KEY(preparation_id,stage_index),UNIQUE(preparation_id,stage_id)
) STRICT;
CREATE TABLE app_collection_legacy_prepared_admissions (
 preparation_id TEXT NOT NULL REFERENCES app_collection_legacy_preparations(id),ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 999),operation_id TEXT NOT NULL,asset_id TEXT NOT NULL,
 body_json TEXT NOT NULL CHECK(json_valid(body_json) AND length(CAST(body_json AS BLOB))<=8192),body_digest TEXT NOT NULL CHECK(length(body_digest)=64 AND body_digest NOT GLOB '*[^0-9a-f]*'),source_proof_digest TEXT NOT NULL CHECK(length(source_proof_digest)=64 AND source_proof_digest NOT GLOB '*[^0-9a-f]*'),current_source_digest TEXT NOT NULL CHECK(length(current_source_digest)=64 AND current_source_digest NOT GLOB '*[^0-9a-f]*'),prior_chain_digest TEXT NOT NULL CHECK(length(prior_chain_digest)=64 AND prior_chain_digest NOT GLOB '*[^0-9a-f]*'),chain_digest TEXT NOT NULL CHECK(length(chain_digest)=64 AND chain_digest NOT GLOB '*[^0-9a-f]*'),run_revision INTEGER NOT NULL CHECK(run_revision BETWEEN 1 AND 9007199254740991),PRIMARY KEY(preparation_id,ordinal),UNIQUE(preparation_id,operation_id),UNIQUE(preparation_id,asset_id)
) STRICT;
CREATE TABLE app_collection_legacy_object_candidates (
 preparation_id TEXT NOT NULL REFERENCES app_collection_legacy_preparations(id),object_key TEXT NOT NULL,
 identity_json TEXT NOT NULL CHECK(json_valid(identity_json) AND length(CAST(identity_json AS BLOB))<=1024),discovery_json TEXT NOT NULL CHECK(json_valid(discovery_json) AND length(CAST(discovery_json AS BLOB))<=2048),discovery_digest TEXT NOT NULL CHECK(length(discovery_digest)=64 AND discovery_digest NOT GLOB '*[^0-9a-f]*'),run_revision INTEGER NOT NULL CHECK(run_revision BETWEEN 1 AND 9007199254740991),PRIMARY KEY(preparation_id,object_key)
) STRICT;
CREATE TABLE app_collection_legacy_prepared_objects (
 preparation_id TEXT NOT NULL,object_key TEXT NOT NULL,
 body_json TEXT NOT NULL CHECK(json_valid(body_json) AND length(CAST(body_json AS BLOB))<=8192),body_digest TEXT NOT NULL CHECK(length(body_digest)=64 AND body_digest NOT GLOB '*[^0-9a-f]*'),prior_chain_digest TEXT NOT NULL CHECK(length(prior_chain_digest)=64 AND prior_chain_digest NOT GLOB '*[^0-9a-f]*'),chain_digest TEXT NOT NULL CHECK(length(chain_digest)=64 AND chain_digest NOT GLOB '*[^0-9a-f]*'),run_revision INTEGER NOT NULL CHECK(run_revision BETWEEN 1 AND 9007199254740991),PRIMARY KEY(preparation_id,object_key),FOREIGN KEY(preparation_id,object_key) REFERENCES app_collection_legacy_object_candidates(preparation_id,object_key)
) STRICT;
CREATE TRIGGER collection_legacy_preparation_initial BEFORE INSERT ON app_collection_legacy_preparations BEGIN
 SELECT RAISE(ABORT,'Adoption preparation begins with empty progress') WHERE NEW.state<>'working' OR NEW.phase<>'inspect' OR NEW.revision<>0 OR NEW.stage_index<>0 OR NEW.admission_index<>0 OR NEW.object_cursor<>0 OR NEW.chain_digest<>NEW.parent_digest OR NEW.quiescence_json IS NOT NULL OR NEW.result_json IS NOT NULL OR NEW.result_digest IS NOT NULL;
 SELECT RAISE(ABORT,'Adoption preparation needs settled audited source') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_economics e WHERE e.id=NEW.economic_audit_id AND e.operator=NEW.operator AND e.state='ready' AND NEW.created_ms>=e.as_of_ms AND NEW.updated_ms=NEW.created_ms AND json_type(e.result_json,'$.admitted') IS 'integer' AND json_extract(e.result_json,'$.admitted') IS json_extract(e.result_json,'$.fulfilled') AND json_extract(e.result_json,'$.counts.pending') IS 0 AND json_extract(e.result_json,'$.historicalEconomics') IS 1 AND json_extract(e.result_json,'$.adoptionAuthorized') IS 0 AND NOT EXISTS(SELECT 1 FROM app_collection_authorities a WHERE a.inventory_id=json_extract(e.result_json,'$.inventoryId')));
END;

CREATE TRIGGER collection_legacy_prepared_stage_insert BEFORE INSERT ON app_collection_legacy_prepared_stages BEGIN
 SELECT RAISE(ABORT,'Prepared stage must extend current adoption prefix') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_preparations a JOIN app_collection_legacy_economics e ON e.id=a.economic_audit_id JOIN app_collection_legacy_relations r ON r.id=e.relation_audit_id JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id JOIN app_collection_legacy_economic_stages proof ON proof.audit_id=e.id AND proof.stage_index=a.stage_index WHERE (((((a.id=NEW.preparation_id AND (a.state='working' AND a.phase='stages')) AND ((a.stage_index=NEW.stage_index AND a.revision+1=NEW.run_revision) AND (a.chain_digest=NEW.prior_chain_digest AND proof.stage_id=NEW.stage_id))) AND ((proof.proof_digest=NEW.source_proof_digest
 AND (json_extract(NEW.body_json,'$.format') IS 'legacy-adoption-stage-prepared-v1' AND json_extract(NEW.body_json,'$.adoptionId') IS a.id)) AND ((json_extract(NEW.body_json,'$.economicAuditId') IS e.id AND json_extract(NEW.body_json,'$.inventoryId') IS p.inventory_id) AND (json_extract(NEW.body_json,'$.rootId') IS p.root_id AND json_extract(NEW.body_json,'$.stageIndex') IS NEW.stage_index)))) AND (((json_extract(NEW.body_json,'$.stageProofDigest') IS proof.proof_digest AND (json_extract(NEW.body_json,'$.originalIdentity') IS proof.original_identity_json AND json_extract(NEW.body_json,'$.stageSourceDigest') IS json_extract(proof.proof_json,'$.value.sourceDigest')
)) AND ((json_extract(NEW.body_json,'$.stage.inventoryId') IS p.inventory_id AND json_extract(NEW.body_json,'$.stage.stageId') IS NEW.stage_id) AND (json_extract(NEW.body_json,'$.stage.ordinal') IS NEW.stage_index AND json_extract(NEW.body_json,'$.stage.commandOperationId') IS NEW.operation_id))) AND (((json_extract(NEW.body_json,'$.stage.termsDigest') IS json_extract(proof.proof_json,'$.value.stageAudit.termsDigest') AND json_type(NEW.body_json,'$.stage.termsJson') IS 'text'
) AND (json_extract(NEW.body_json,'$.command.operationId') IS NEW.operation_id AND json_extract(NEW.body_json,'$.command.claimNonce') IS NEW.claim_nonce)) AND ((json_extract(NEW.body_json,'$.command.requestKey') IS NEW.request_key AND json_extract(NEW.body_json,'$.command.operationKind') IS 'collection.adopt-legacy-stage.v1') AND (json_extract(NEW.body_json,'$.command.principal.kind') IS 'operator' AND json_extract(NEW.body_json,'$.command.principal.id') IS a.operator))))) AND ((((json_extract(NEW.body_json,'$.command.businessIdentity') IS json_array(a.id,p.root_id,NEW.stage_id) AND (json_extract(NEW.body_json,'$.command.resultRef') IS json_array(p.inventory_id,NEW.stage_id)
 AND json_extract(NEW.body_json,'$.command.input.adoptionId') IS a.id)) AND ((json_extract(NEW.body_json,'$.command.input.economicAuditId') IS e.id AND json_extract(NEW.body_json,'$.command.input.inventoryId') IS p.inventory_id) AND (json_extract(NEW.body_json,'$.command.input.rootId') IS p.root_id AND json_extract(NEW.body_json,'$.command.input.stageId') IS NEW.stage_id))) AND (((json_extract(NEW.body_json,'$.command.input.stageIndex') IS NEW.stage_index AND json_extract(NEW.body_json,'$.command.input.termsDigest') IS json_extract(proof.proof_json,'$.value.stageAudit.termsDigest')) AND (json_extract(NEW.body_json,'$.command.input.economicSelectionDigest') IS e.selection_digest AND json_extract(NEW.body_json,'$.command.input.economicChainDigest') IS e.chain_digest)) AND ((json_extract(NEW.body_json,'$.command.input.stageProofDigest') IS proof.proof_digest
 AND json_extract(NEW.body_json,'$.command.result.adoptionId') IS a.id) AND (json_extract(NEW.body_json,'$.command.result.inventoryId') IS p.inventory_id AND json_extract(NEW.body_json,'$.command.result.stageId') IS NEW.stage_id)))) AND (((json_extract(NEW.body_json,'$.command.result.termsDigest') IS json_extract(proof.proof_json,'$.value.stageAudit.termsDigest') AND (json_extract(NEW.body_json,'$.command.result.authorityRevision') IS 0 AND json_extract(NEW.body_json,'$.command.result.imported') IS 1)) AND ((json_extract(NEW.body_json,'$.command.result.source') IS 'local-fixture' AND json_extract(NEW.body_json,'$.command.result.executable') IS 0
) AND (json_type(NEW.body_json,'$.command.inputDigest') IS 'text' AND length(json_extract(NEW.body_json,'$.command.inputDigest'))=64))) AND (((json_extract(NEW.body_json,'$.command.inputDigest') NOT GLOB '*[^0-9a-f]*' AND json_type(NEW.body_json,'$.command.requestDigest') IS 'text') AND (length(json_extract(NEW.body_json,'$.command.requestDigest'))=64 AND json_extract(NEW.body_json,'$.command.requestDigest') NOT GLOB '*[^0-9a-f]*')) AND ((json_type(NEW.body_json,'$.command.outputDigest') IS 'text' AND length(json_extract(NEW.body_json,'$.command.outputDigest'))=64) AND (json_extract(NEW.body_json,'$.command.outputDigest') NOT GLOB '*[^0-9a-f]*'
 AND EXISTS(SELECT 1 FROM app_collection_legacy_object_candidates o WHERE o.preparation_id=a.id AND o.object_key=json_extract(NEW.body_json,'$.originalIdentity.key') AND o.identity_json IS json_extract(NEW.body_json,'$.originalIdentity')))))))));
END;
CREATE TRIGGER collection_legacy_prepared_stages_no_update BEFORE UPDATE ON app_collection_legacy_prepared_stages BEGIN SELECT RAISE(ABORT,'Retain immutable adoption preparation evidence'); END;
CREATE TRIGGER collection_legacy_prepared_stages_no_delete BEFORE DELETE ON app_collection_legacy_prepared_stages BEGIN SELECT RAISE(ABORT,'Retain immutable adoption preparation evidence'); END;
