CREATE TRIGGER collection_legacy_preparation_quiescence BEFORE UPDATE ON app_collection_legacy_preparations WHEN NEW.state<>'held' AND NEW.phase<>'inspect' BEGIN
 SELECT RAISE(ABORT,'Missing exact typed inventory quiescence') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_economics e JOIN app_collection_legacy_relations r ON r.id=e.relation_audit_id JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id CROSS JOIN (SELECT CASE WHEN NEW.phase IN ('closure','objects','admissions','stages') THEN NEW.quiescence_json ELSE json_extract(NEW.quiescence_json,'$.current') END body) q WHERE (((((e.id=NEW.economic_audit_id AND json_type(q.body) IS 'object') AND (json_extract(q.body,'$.kind') IS 'verified' AND (json_extract(q.body,'$.rootId') IS p.root_id AND json_extract(q.body,'$.sourcePin.inventoryId') IS p.inventory_id))) AND ((json_extract(q.body,'$.sourcePin.sourceRevision') IS CAST(p.source_revision AS TEXT) AND (json_extract(q.body,'$.sourcePin.generation') IS json_extract(p.descriptor_json,'$.sourceGeneration') AND json_extract(q.body,'$.sourcePin.watermark') IS json_extract(p.descriptor_json,'$.sourceWatermark'))) AND (json_type(q.body,'$.sourceDigest') IS 'text' AND (length(json_extract(q.body,'$.sourceDigest'))=64 AND json_extract(q.body,'$.sourceDigest') NOT GLOB '*[^0-9a-f]*')))) AND (((json_extract(q.body,'$.quiescent') IS 1 AND json_extract(q.body,'$.verification') IS 'inventory-quiescence-and-binding-closure') AND (json_extract(q.body,'$.prefixAuthority') IS 0 AND (json_extract(q.body,'$.economics') IS 0 AND json_extract(q.body,'$.adoption') IS 0))) AND ((json_type(q.body,'$.counts') IS 'object' AND ((SELECT COUNT(*) FROM json_each(q.body,'$.counts'))=13 AND json_type(q.body,'$.counts.admissionCount') IS 'integer')) AND (json_extract(q.body,'$.counts.admissionCount') IS json_extract(e.result_json,'$.admitted') AND (json_type(q.body,'$.counts.fulfilledCount') IS 'integer' AND json_extract(q.body,'$.counts.fulfilledCount') IS json_extract(e.result_json,'$.admitted')))))) AND ((((json_type(q.body,'$.counts.mintOperations') IS 'integer' AND json_extract(q.body,'$.counts.mintOperations') IS json_extract(e.result_json,'$.admitted')) AND (json_type(q.body,'$.counts.distinctMintAssets') IS 'integer' AND (json_extract(q.body,'$.counts.distinctMintAssets') IS json_extract(e.result_json,'$.admitted') AND json_type(q.body,'$.counts.collectAssets') IS 'integer'))) AND ((json_extract(q.body,'$.counts.collectAssets') IS json_extract(e.result_json,'$.admitted') AND (json_type(q.body,'$.counts.vaultBindings') IS 'integer' AND json_extract(q.body,'$.counts.vaultBindings') IS json_extract(e.result_json,'$.admitted'))) AND (json_type(q.body,'$.counts.pendingOperations') IS 'integer' AND (json_extract(q.body,'$.counts.pendingOperations') IS 0 AND json_type(q.body,'$.counts.lockedAssets') IS 'integer')))) AND (((json_extract(q.body,'$.counts.lockedAssets') IS 0 AND json_type(q.body,'$.counts.heldConflicts') IS 'integer') AND (json_extract(q.body,'$.counts.heldConflicts') IS 0 AND (json_type(q.body,'$.counts.malformedOperations') IS 'integer' AND json_extract(q.body,'$.counts.malformedOperations') IS 0))) AND ((json_type(q.body,'$.counts.unboundAssets') IS 'integer' AND (json_extract(q.body,'$.counts.unboundAssets') IS 0 AND json_type(q.body,'$.counts.missingVaultBindings') IS 'integer')) AND (json_extract(q.body,'$.counts.missingVaultBindings') IS 0 AND (json_type(q.body,'$.counts.extraVaultBindings') IS 'integer' AND json_extract(q.body,'$.counts.extraVaultBindings') IS 0)))))));
END;




-- Generated remaining guards
CREATE TRIGGER collection_legacy_prepared_stage_projection BEFORE INSERT ON app_collection_legacy_prepared_stages  BEGIN
 SELECT RAISE(ABORT,'Prepared stage projection must retain exact terms and eligibility') WHERE NOT EXISTS(SELECT 1 WHERE json_type(NEW.body_json,'$.stage.termsJson') IS 'text' AND json_valid(json_extract(NEW.body_json,'$.stage.termsJson')) AND json_extract(NEW.body_json,'$.stage.stageId') IS json_extract(json_extract(NEW.body_json,'$.stage.termsJson'),'$.id') AND json_extract(NEW.body_json,'$.stage.stageType') IS json_extract(json_extract(NEW.body_json,'$.stage.termsJson'),'$.type') AND json_extract(NEW.body_json,'$.stage.publishedMs') IS json_extract(json_extract(NEW.body_json,'$.stage.termsJson'),'$.publishedAt') AND json_extract(NEW.body_json,'$.stage.opensMs') IS json_extract(json_extract(NEW.body_json,'$.stage.termsJson'),'$.opensAt') AND json_extract(NEW.body_json,'$.stage.closesMs') IS json_extract(json_extract(NEW.body_json,'$.stage.termsJson'),'$.closesAt') AND json_extract(NEW.body_json,'$.stage.termsDigest') IS json_extract(json_extract(NEW.body_json,'$.stage.termsJson'),'$.termsDigest') AND json_extract(NEW.body_json,'$.stage.eligibilityKind') IS json_extract(NEW.body_json,'$.command.result.eligibility.kind') AND json_extract(NEW.body_json,'$.stage.listId') IS json_extract(NEW.body_json,'$.command.result.eligibility.listId') AND json_extract(NEW.body_json,'$.stage.eligibleCount') IS json_extract(NEW.body_json,'$.command.result.eligibility.count') AND json_extract(NEW.body_json,'$.stage.stageType') IN ('whitelist','founder','public','free') AND json_type(NEW.body_json,'$.stage.publishedMs') IS 'integer' AND json_type(NEW.body_json,'$.stage.opensMs') IS 'integer' AND json_type(NEW.body_json,'$.stage.closesMs') IS 'integer' AND json_extract(NEW.body_json,'$.stage.publishedMs')>=0 AND json_extract(NEW.body_json,'$.stage.opensMs')>=json_extract(NEW.body_json,'$.stage.publishedMs') AND json_extract(NEW.body_json,'$.stage.closesMs')>json_extract(NEW.body_json,'$.stage.opensMs') AND ((json_extract(NEW.body_json,'$.stage.stageType') IN ('whitelist','founder') AND json_extract(NEW.body_json,'$.stage.eligibilityKind') IS 'list' AND json_type(NEW.body_json,'$.stage.listId') IS 'text' AND length(json_extract(NEW.body_json,'$.stage.listId'))=64 AND json_extract(NEW.body_json,'$.stage.listId') NOT GLOB '*[^0-9a-f]*' AND json_type(NEW.body_json,'$.stage.eligibleCount') IS 'integer' AND json_extract(NEW.body_json,'$.stage.eligibleCount') BETWEEN 0 AND 10000 AND json_type(NEW.body_json,'$.historicalFree') IS 'null') OR (json_extract(NEW.body_json,'$.stage.stageType') IS 'public' AND json_extract(NEW.body_json,'$.stage.eligibilityKind') IS 'unrestricted' AND json_type(NEW.body_json,'$.stage.listId') IS 'null' AND json_type(NEW.body_json,'$.stage.eligibleCount') IS 'null' AND json_type(NEW.body_json,'$.historicalFree') IS 'null') OR (json_extract(NEW.body_json,'$.stage.stageType') IS 'free' AND json_extract(NEW.body_json,'$.stage.eligibilityKind') IS 'pending' AND json_type(NEW.body_json,'$.stage.listId') IS 'null' AND json_type(NEW.body_json,'$.stage.eligibleCount') IS 'null' AND json_type(NEW.body_json,'$.historicalFree') IS 'object')));

END;
CREATE TRIGGER collection_legacy_prepared_admission_insert BEFORE INSERT ON app_collection_legacy_prepared_admissions  BEGIN
 SELECT RAISE(ABORT,'Prepared admission must retain exact audited source facts') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_preparations a JOIN app_collection_legacy_economics e ON e.id=a.economic_audit_id JOIN app_collection_legacy_relations r ON r.id=e.relation_audit_id JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id WHERE (((((a.id=NEW.preparation_id AND a.state='working') AND (a.phase='admissions' AND (a.admission_index=NEW.ordinal AND a.revision+1=NEW.run_revision))) AND ((a.chain_digest=NEW.prior_chain_digest AND (json_extract(NEW.body_json,'$.format') IS 'legacy-adoption-mint-anchor-v1' AND json_extract(NEW.body_json,'$.adoptionId') IS a.id)) AND (json_extract(NEW.body_json,'$.economicAuditId') IS e.id AND (json_extract(NEW.body_json,'$.inventoryId') IS p.inventory_id AND json_extract(NEW.body_json,'$.rootId') IS p.root_id)))) AND (((json_extract(NEW.body_json,'$.ordinal') IS NEW.ordinal AND (json_extract(NEW.body_json,'$.operation.id') IS NEW.operation_id AND json_extract(NEW.body_json,'$.originalOutcome.assetId') IS NEW.asset_id)) AND (json_extract(NEW.body_json,'$.current.assetId') IS NEW.asset_id AND (json_extract(NEW.body_json,'$.current.operationId') IS NEW.operation_id AND json_extract(NEW.body_json,'$.current.ordinal') IS NEW.ordinal))) AND ((json_extract(NEW.body_json,'$.current.rootId') IS p.root_id AND (json_extract(NEW.body_json,'$.current.sourceDigest') IS NEW.current_source_digest AND json_extract(NEW.body_json,'$.current.kind') IS 'verified')) AND (json_extract(NEW.body_json,'$.current.verification') IS 'historical-current-asset-consistency' AND (json_extract(NEW.body_json,'$.current.prefixAuthority') IS 0 AND json_extract(NEW.body_json,'$.current.economics') IS 0))))) AND ((((json_extract(NEW.body_json,'$.current.adoption') IS 0 AND (json_extract(NEW.body_json,'$.current.counts.completedProgressions') IS 0 AND json_extract(NEW.body_json,'$.current.sourcePin.inventoryId') IS p.inventory_id)) AND (json_extract(NEW.body_json,'$.current.sourcePin.sourceRevision') IS CAST(p.source_revision AS TEXT) AND (json_extract(NEW.body_json,'$.current.sourcePin.generation') IS json_extract(p.descriptor_json,'$.sourceGeneration') AND json_extract(NEW.body_json,'$.current.sourcePin.watermark') IS json_extract(p.descriptor_json,'$.sourceWatermark')))) AND ((json_type(NEW.body_json,'$.current.currentAssetDigest') IS 'text' AND (length(json_extract(NEW.body_json,'$.current.currentAssetDigest'))=64 AND json_extract(NEW.body_json,'$.current.currentAssetDigest') NOT GLOB '*[^0-9a-f]*')) AND (json_type(NEW.body_json,'$.prefixBeforeDigest') IS 'text' AND (length(json_extract(NEW.body_json,'$.prefixBeforeDigest'))=64 AND json_extract(NEW.body_json,'$.prefixBeforeDigest') NOT GLOB '*[^0-9a-f]*')))) AND (((json_type(NEW.body_json,'$.prefixAfterDigest') IS 'text' AND (length(json_extract(NEW.body_json,'$.prefixAfterDigest'))=64 AND json_extract(NEW.body_json,'$.prefixAfterDigest') NOT GLOB '*[^0-9a-f]*')) AND (EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases x WHERE x.audit_id=e.id AND x.ordinal=NEW.ordinal AND x.phase='select' AND json_extract(NEW.body_json,'$.phaseProofs.select.proofDigest') IS x.proof_digest AND json_extract(NEW.body_json,'$.phaseProofs.select.chainDigest') IS x.chain_digest AND json_extract(NEW.body_json,'$.original') IS json_extract(x.body_json,'$.value')) AND (EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases x WHERE x.audit_id=e.id AND x.ordinal=NEW.ordinal AND x.phase='prepare' AND json_extract(NEW.body_json,'$.phaseProofs.prepare.proofDigest') IS x.proof_digest AND json_extract(NEW.body_json,'$.phaseProofs.prepare.chainDigest') IS x.chain_digest AND json_extract(NEW.body_json,'$.operation.id') IS json_extract(x.body_json,'$.value.operation.id') AND json_extract(NEW.body_json,'$.operation.wallet') IS json_extract(x.body_json,'$.value.operation.owner') AND json_extract(NEW.body_json,'$.operation.requestKey') IS json_extract(x.body_json,'$.value.operation.request_key') AND json_extract(NEW.body_json,'$.operation.requestDigest') IS json_extract(x.body_json,'$.value.operation.request_digest') AND json_extract(NEW.body_json,'$.operation.commitment') IS json_extract(x.body_json,'$.value.operation.commitment') AND json_extract(NEW.body_json,'$.operation.admittedAtMs') IS json_extract(x.body_json,'$.value.operation.created_ms') AND json_extract(NEW.body_json,'$.operation.settledAtMs') IS json_extract(x.body_json,'$.value.operation.settled_ms') AND json_extract(NEW.body_json,'$.operation.proofId') IS json_extract(x.body_json,'$.value.operation.proof_id') AND json_extract(NEW.body_json,'$.operation.evidenceDigest') IS json_extract(x.body_json,'$.value.operation.evidence_digest')) AND EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases x WHERE x.audit_id=e.id AND x.ordinal=NEW.ordinal AND x.phase='control' AND json_extract(NEW.body_json,'$.phaseProofs.control.proofDigest') IS x.proof_digest AND json_extract(NEW.body_json,'$.phaseProofs.control.chainDigest') IS x.chain_digest AND json_extract(NEW.body_json,'$.controlFact') IS json_extract(x.body_json,'$.value.controlFact') AND json_extract(NEW.body_json,'$.controlSelectionIdentity.byteDigest') IS json_extract(x.body_json,'$.value.controlFact.sourceDigest'))))) AND ((EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases x WHERE x.audit_id=e.id AND x.ordinal=NEW.ordinal AND x.phase='mint' AND json_extract(NEW.body_json,'$.phaseProofs.mint.proofDigest') IS x.proof_digest AND json_extract(NEW.body_json,'$.phaseProofs.mint.chainDigest') IS x.chain_digest AND json_extract(NEW.body_json,'$.originalOutcome') IS json_extract(x.body_json,'$.value.audit.summary')) AND (EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases x WHERE x.audit_id=e.id AND x.ordinal=NEW.ordinal AND x.phase='membership' AND json_extract(NEW.body_json,'$.phaseProofs.membership.proofDigest') IS x.proof_digest AND json_extract(NEW.body_json,'$.phaseProofs.membership.chainDigest') IS x.chain_digest) AND EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases x WHERE x.audit_id=e.id AND x.ordinal=NEW.ordinal AND x.phase='advance' AND json_extract(NEW.body_json,'$.phaseProofs.advance.proofDigest') IS x.proof_digest AND json_extract(NEW.body_json,'$.phaseProofs.advance.chainDigest') IS x.chain_digest AND x.proof_digest=NEW.source_proof_digest AND json_extract(NEW.body_json,'$.economics.termsDigest') IS json_extract(x.body_json,'$.value.summary.termsDigest') AND json_extract(NEW.body_json,'$.economics.priceLamports') IS json_extract(x.body_json,'$.value.summary.priceLamports') AND json_extract(NEW.body_json,'$.economics.costLamports') IS json_extract(x.body_json,'$.value.summary.costLamports') AND json_extract(NEW.body_json,'$.operation.stageId') IS json_extract(x.body_json,'$.value.summary.stageId')))) AND (EXISTS(SELECT 1 FROM app_collection_legacy_prepared_stages t WHERE t.preparation_id=a.id AND t.stage_id=json_extract(NEW.body_json,'$.operation.stageId') AND t.source_proof_digest=json_extract(NEW.body_json,'$.stageProofDigest')) AND (EXISTS(SELECT 1 FROM app_collection_legacy_object_candidates c WHERE c.preparation_id=a.id AND c.identity_json IS CASE json_extract(NEW.body_json,'$.original.kind') WHEN 'manual' THEN json_extract(NEW.body_json,'$.original.fixture') WHEN 'configured' THEN json_extract(NEW.body_json,'$.original.policy') END) AND EXISTS(SELECT 1 FROM app_collection_legacy_object_candidates c WHERE c.preparation_id=a.id AND c.identity_json IS json_extract(NEW.body_json,'$.controlSelectionIdentity')))))))));

END;
CREATE TRIGGER collection_legacy_preparation_candidate_insert BEFORE INSERT ON app_collection_legacy_object_candidates  BEGIN
 SELECT RAISE(ABORT,'Candidate needs a current typed discovery') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_preparations a WHERE ((((a.id=NEW.preparation_id AND a.state='working') AND (a.revision+1=NEW.run_revision AND json_extract(NEW.identity_json,'$.key') IS NEW.object_key)) AND ((json_extract(NEW.identity_json,'$.key') IS 'private/'||json_extract(NEW.identity_json,'$.byteDigest')||'.json' AND json_type(NEW.identity_json,'$.byteDigest') IS 'text') AND (length(json_extract(NEW.identity_json,'$.byteDigest'))=64 AND (json_extract(NEW.identity_json,'$.byteDigest') NOT GLOB '*[^0-9a-f]*' AND json_extract(NEW.identity_json,'$.visibility') IS 'private')))) AND (((json_extract(NEW.identity_json,'$.contentType') IS 'application/json' AND json_type(NEW.identity_json,'$.size') IS 'integer') AND (json_extract(NEW.identity_json,'$.size') BETWEEN 1 AND 147456 AND (json_type(NEW.identity_json,'$.semanticDigest') IS 'null' OR (json_type(NEW.identity_json,'$.semanticDigest') IS 'text' AND length(json_extract(NEW.identity_json,'$.semanticDigest'))=64 AND json_extract(NEW.identity_json,'$.semanticDigest') NOT GLOB '*[^0-9a-f]*')))) AND (((SELECT COUNT(*) FROM json_each(NEW.identity_json))=6 AND json_extract(NEW.discovery_json,'$.format') IS 'legacy-adoption-object-discovery-v1') AND (json_extract(NEW.discovery_json,'$.phase') IS a.phase AND (((json_extract(NEW.discovery_json,'$.role') IS 'stage-original' AND a.phase='stages' AND json_extract(NEW.discovery_json,'$.index') IS a.stage_index AND json_type(NEW.discovery_json,'$.parentKey') IS 'null') OR (json_extract(NEW.discovery_json,'$.role') IN ('manual-mint','configured-policy','historical-control') AND a.phase='admissions' AND json_extract(NEW.discovery_json,'$.index') IS a.admission_index AND json_type(NEW.discovery_json,'$.parentKey') IS 'null') OR (json_extract(NEW.discovery_json,'$.role') IS 'policy-part' AND a.phase='objects' AND json_extract(NEW.discovery_json,'$.index') IS a.object_cursor AND json_type(NEW.discovery_json,'$.parentKey') IS 'text')) AND json_extract(NEW.identity_json,'$.size')<=CASE json_extract(NEW.discovery_json,'$.role') WHEN 'stage-original' THEN 16384 WHEN 'policy-part' THEN 65536 WHEN 'historical-control' THEN 147456 ELSE 8192 END))))));

END;
CREATE TRIGGER collection_legacy_preparation_candidate_budget BEFORE INSERT ON app_collection_legacy_object_candidates  BEGIN
 SELECT RAISE(ABORT,'Preparation object closure exceeds bounded capacity') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_object_candidates WHERE preparation_id=NEW.preparation_id AND object_key=NEW.object_key) AND ((SELECT COUNT(*) FROM app_collection_legacy_object_candidates WHERE preparation_id=NEW.preparation_id)>=2048 OR (SELECT COALESCE(SUM(json_extract(identity_json,'$.size')),0) FROM app_collection_legacy_object_candidates WHERE preparation_id=NEW.preparation_id)+json_extract(NEW.identity_json,'$.size')>16777216);

END;
CREATE TRIGGER collection_legacy_prepared_object_insert BEFORE INSERT ON app_collection_legacy_prepared_objects  BEGIN
 SELECT RAISE(ABORT,'Prepared object requires exact candidate and discovered children') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_preparations a JOIN app_collection_legacy_object_candidates c ON c.preparation_id=a.id WHERE (((a.id=NEW.preparation_id AND (a.state='working' AND a.phase='objects')) AND (a.revision+1=NEW.run_revision AND (a.chain_digest=NEW.prior_chain_digest AND c.object_key=NEW.object_key))) AND ((json_extract(NEW.body_json,'$.format') IS 'legacy-adoption-object-proof-v1' AND (json_extract(NEW.body_json,'$.adoptionId') IS a.id AND json_extract(NEW.body_json,'$.identity') IS c.identity_json)) AND ((json_type(NEW.body_json,'$.descriptorChildren') IS 'array' AND json_array_length(NEW.body_json,'$.descriptorChildren')<=13) AND ((json_extract(c.discovery_json,'$.role')='configured-policy' OR json_array_length(NEW.body_json,'$.descriptorChildren')=0) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.body_json,'$.descriptorChildren') z WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_object_candidates k WHERE k.preparation_id=a.id AND k.identity_json IS z.value)))))));

END;
CREATE TRIGGER collection_legacy_preparation_update BEFORE UPDATE ON app_collection_legacy_preparations  BEGIN
 SELECT RAISE(ABORT,'Retain adoption preparation identity') WHERE NEW.id<>OLD.id OR NEW.economic_audit_id<>OLD.economic_audit_id OR NEW.operator<>OLD.operator OR NEW.parent_digest<>OLD.parent_digest OR NEW.created_ms<>OLD.created_ms OR OLD.state<>'working' OR NEW.revision<>OLD.revision+1 OR NEW.last_nonce=OLD.last_nonce OR NEW.updated_ms<OLD.updated_ms;
 SELECT RAISE(ABORT,'Held preparation retains exact progress') WHERE NEW.state='held' AND (NEW.phase<>OLD.phase OR NEW.stage_index<>OLD.stage_index OR NEW.admission_index<>OLD.admission_index OR NEW.object_cursor<>OLD.object_cursor OR NEW.chain_digest<>OLD.chain_digest OR NEW.quiescence_json IS NOT OLD.quiescence_json);
 SELECT RAISE(ABORT,'Invalid preparation phase transition') WHERE NEW.state<>'held' AND NOT ((OLD.phase='inspect' AND NEW.phase=CASE WHEN (SELECT COUNT(*) FROM app_collection_legacy_economic_stages WHERE audit_id=NEW.economic_audit_id)>0 THEN 'stages' WHEN (SELECT json_extract(result_json,'$.admitted') FROM app_collection_legacy_economics WHERE id=NEW.economic_audit_id)>0 THEN 'admissions' ELSE 'objects' END AND NEW.stage_index=0 AND NEW.admission_index=0 AND NEW.object_cursor=0 AND NEW.chain_digest=OLD.chain_digest) OR (OLD.phase='stages' AND NEW.stage_index=OLD.stage_index+1 AND NEW.stage_index<=(SELECT COUNT(*) FROM app_collection_legacy_economic_stages WHERE audit_id=NEW.economic_audit_id) AND NEW.phase=CASE WHEN NEW.stage_index=(SELECT COUNT(*) FROM app_collection_legacy_economic_stages WHERE audit_id=NEW.economic_audit_id) THEN CASE WHEN (SELECT json_extract(result_json,'$.admitted') FROM app_collection_legacy_economics WHERE id=NEW.economic_audit_id)>0 THEN 'admissions' ELSE 'objects' END ELSE 'stages' END AND NEW.admission_index=OLD.admission_index AND NEW.object_cursor=OLD.object_cursor) OR (OLD.phase='admissions' AND NEW.admission_index=OLD.admission_index+1 AND NEW.admission_index<=(SELECT json_extract(result_json,'$.admitted') FROM app_collection_legacy_economics WHERE id=NEW.economic_audit_id) AND NEW.phase=CASE WHEN NEW.admission_index=(SELECT json_extract(result_json,'$.admitted') FROM app_collection_legacy_economics WHERE id=NEW.economic_audit_id) THEN 'objects' ELSE 'admissions' END AND NEW.stage_index=OLD.stage_index AND NEW.object_cursor=OLD.object_cursor) OR (OLD.phase='objects' AND NEW.phase='objects' AND NEW.object_cursor=OLD.object_cursor+1 AND NEW.stage_index=OLD.stage_index AND NEW.admission_index=OLD.admission_index) OR (OLD.phase='objects' AND NEW.phase='closure' AND NEW.object_cursor=OLD.object_cursor AND NEW.stage_index=OLD.stage_index AND NEW.admission_index=OLD.admission_index AND NEW.chain_digest=OLD.chain_digest) OR (OLD.phase='closure' AND NEW.phase='finish' AND NEW.object_cursor=OLD.object_cursor AND NEW.stage_index=OLD.stage_index AND NEW.admission_index=OLD.admission_index AND NEW.chain_digest=OLD.chain_digest AND json_extract(NEW.quiescence_json,'$.current') IS OLD.quiescence_json) OR (OLD.phase='finish' AND NEW.phase='finish' AND NEW.state='prepared' AND NEW.object_cursor=OLD.object_cursor AND NEW.stage_index=OLD.stage_index AND NEW.admission_index=OLD.admission_index AND NEW.chain_digest=OLD.chain_digest));
 SELECT RAISE(ABORT,'Prepared result needs completed closure') WHERE NEW.state='prepared' AND OLD.phase<>'finish';
 SELECT RAISE(ABORT,'Retain fixed quiescence during preparation') WHERE NEW.state<>'held' AND OLD.phase NOT IN ('inspect','closure') AND NEW.quiescence_json IS NOT OLD.quiescence_json;
 SELECT RAISE(ABORT,'Missing exact prepared stages effect') WHERE NEW.state<>'held' AND OLD.phase='stages' AND NEW.stage_index=OLD.stage_index+1 AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_prepared_stages c WHERE c.preparation_id=OLD.id AND c.stage_index=OLD.stage_index AND c.run_revision=NEW.revision AND c.prior_chain_digest=OLD.chain_digest AND c.chain_digest=NEW.chain_digest);
 SELECT RAISE(ABORT,'Prepared stages prefix count changed') WHERE NEW.state<>'held' AND NEW.stage_index<>(SELECT COUNT(*) FROM app_collection_legacy_prepared_stages WHERE preparation_id=NEW.id);
 SELECT RAISE(ABORT,'Missing exact prepared admissions effect') WHERE NEW.state<>'held' AND OLD.phase='admissions' AND NEW.admission_index=OLD.admission_index+1 AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_prepared_admissions c WHERE c.preparation_id=OLD.id AND c.ordinal=OLD.admission_index AND c.run_revision=NEW.revision AND c.prior_chain_digest=OLD.chain_digest AND c.chain_digest=NEW.chain_digest);
 SELECT RAISE(ABORT,'Prepared admissions prefix count changed') WHERE NEW.state<>'held' AND NEW.admission_index<>(SELECT COUNT(*) FROM app_collection_legacy_prepared_admissions WHERE preparation_id=NEW.id);
 SELECT RAISE(ABORT,'Missing exact prepared objects effect') WHERE NEW.state<>'held' AND OLD.phase='objects' AND NEW.object_cursor=OLD.object_cursor+1 AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_prepared_objects c WHERE c.preparation_id=OLD.id AND c.run_revision=NEW.revision AND c.prior_chain_digest=OLD.chain_digest AND c.chain_digest=NEW.chain_digest);
 SELECT RAISE(ABORT,'Prepared objects prefix count changed') WHERE NEW.state<>'held' AND NEW.object_cursor<>(SELECT COUNT(*) FROM app_collection_legacy_prepared_objects WHERE preparation_id=NEW.id);
 SELECT RAISE(ABORT,'Closure requires all candidates verified') WHERE NEW.state<>'held' AND NEW.phase IN ('closure','finish') AND (NEW.object_cursor<>(SELECT COUNT(*) FROM app_collection_legacy_object_candidates WHERE preparation_id=NEW.id) OR NEW.stage_index<>(SELECT COUNT(*) FROM app_collection_legacy_economic_stages WHERE audit_id=NEW.economic_audit_id) OR NEW.admission_index<>(SELECT json_extract(result_json,'$.admitted') FROM app_collection_legacy_economics WHERE id=NEW.economic_audit_id));

END;
CREATE TRIGGER collection_legacy_preparation_closure BEFORE UPDATE ON app_collection_legacy_preparations WHEN NEW.state<>'held' AND NEW.phase='finish' BEGIN
 SELECT RAISE(ABORT,'Object closure must equal the exact reference set') WHERE EXISTS(WITH expected AS (SELECT json_extract(body_json,'$.originalIdentity') identity FROM app_collection_legacy_prepared_stages WHERE preparation_id=NEW.id UNION SELECT CASE json_extract(body_json,'$.original.kind') WHEN 'manual' THEN json_extract(body_json,'$.original.fixture') WHEN 'configured' THEN json_extract(body_json,'$.original.policy') END FROM app_collection_legacy_prepared_admissions WHERE preparation_id=NEW.id UNION SELECT json_extract(body_json,'$.controlSelectionIdentity') FROM app_collection_legacy_prepared_admissions WHERE preparation_id=NEW.id UNION SELECT z.value FROM app_collection_legacy_prepared_objects o,json_each(o.body_json,'$.descriptorChildren') z WHERE o.preparation_id=NEW.id) SELECT 1 FROM expected x WHERE x.identity IS NULL OR NOT EXISTS(SELECT 1 FROM app_collection_legacy_object_candidates c WHERE c.preparation_id=NEW.id AND c.identity_json IS x.identity) UNION ALL SELECT 1 FROM app_collection_legacy_object_candidates c WHERE c.preparation_id=NEW.id AND NOT EXISTS(SELECT 1 FROM expected x WHERE x.identity IS c.identity_json));
 SELECT RAISE(ABORT,'Missing exact object closure totals') WHERE NOT EXISTS(SELECT 1 WHERE json_type(NEW.quiescence_json,'$.objects') IS 'object' AND (SELECT COUNT(*) FROM json_each(NEW.quiescence_json,'$.objects'))=3 AND json_extract(NEW.quiescence_json,'$.objects.count') IS NEW.object_cursor AND json_extract(NEW.quiescence_json,'$.objects.expectedCount') IS NEW.object_cursor AND json_type(NEW.quiescence_json,'$.objects.totalBytes') IS 'integer' AND json_extract(NEW.quiescence_json,'$.objects.totalBytes') IS (SELECT COALESCE(SUM(json_extract(identity_json,'$.size')),0) FROM app_collection_legacy_object_candidates WHERE preparation_id=NEW.id) AND json_extract(NEW.quiescence_json,'$.objects.totalBytes') BETWEEN 0 AND 16777216);

END;
CREATE TRIGGER collection_legacy_preparation_ready BEFORE UPDATE ON app_collection_legacy_preparations WHEN NEW.state='prepared' BEGIN
 SELECT RAISE(ABORT,'Missing exact nonauthoritative prepared result') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_preparations a JOIN app_collection_legacy_economics e ON e.id=a.economic_audit_id JOIN app_collection_legacy_relations r ON r.id=e.relation_audit_id JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id WHERE ((((a.id=NEW.id AND json_extract(NEW.result_json,'$.format') IS 'legacy-adoption-prepared-v1') AND (json_extract(NEW.result_json,'$.adoptionId') IS NEW.id AND json_extract(NEW.result_json,'$.economicAuditId') IS NEW.economic_audit_id)) AND ((json_extract(NEW.result_json,'$.inventoryId') IS p.inventory_id AND json_extract(NEW.result_json,'$.rootId') IS p.root_id) AND (json_extract(NEW.result_json,'$.parentDigest') IS NEW.parent_digest AND (json_extract(NEW.result_json,'$.preparationDigest') IS NEW.chain_digest AND json_extract(NEW.result_json,'$.stageCount') IS NEW.stage_index)))) AND (((json_extract(NEW.result_json,'$.admissionCount') IS NEW.admission_index AND json_extract(NEW.result_json,'$.objectCount') IS NEW.object_cursor) AND (json_extract(NEW.result_json,'$.objectBytes') IS json_extract(NEW.quiescence_json,'$.objects.totalBytes') AND (json_extract(NEW.result_json,'$.preparedOnly') IS 1 AND json_extract(NEW.result_json,'$.adoptionAuthorized') IS 0))) AND ((json_extract(NEW.result_json,'$.executable') IS 0 AND json_type(NEW.result_json,'$.quiescenceDigest') IS 'text') AND (length(json_extract(NEW.result_json,'$.quiescenceDigest'))=64 AND (json_extract(NEW.result_json,'$.quiescenceDigest') NOT GLOB '*[^0-9a-f]*' AND (SELECT COUNT(*) FROM json_each(NEW.result_json))=15))))));

END;
